mapper.update:
update emp
username = #{username},
password=#{password},
name = #{name},
gender=#{gender}, phone =#{phone}, job=#{job}, salary=#{salary}, image =#{image}, entry_date=#{entryDate}, dept_id=#{deptId}, update_time=#{updateTime}
where id =#{id}

mapper.select:
select e.*,d.name deptName from emp e left join dept d on e.dept_id=d.id


    e.name like concat('%',#{name},'%')


    and e.gender =#{gender}


    and e.entry_date between #{begin} and #{end}


order by e.update_time desc

select -- emp 的字段，照旧 e.id, e.username, e.password, e.name, e.gender, e.phone, e.job, e.salary, e.image, e.entry_date, e.dept_id, e.create_time, e.update_time,
-- 这里是关键：给 emp_expr 的列起“新名字” ee.id as expr_id, ee.emp_id as expr_emp_id, ee.begin as expr_begin, ee.end as expr_end, ee.company as expr_company, ee.job as expr_job
from emp e left join emp_expr ee on e.id = ee.emp_id where e.id = #{id}
